using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class NurseSeamAudit {
 public static void VerifyContinuous(){NurseHairMaterials.VerifyCandidateBindings();Run();}
 public static void Run(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/EntityStudioGenerated/RebirthNurseNative/RebirthNurse_Authoring.prefab"));var r=go.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(x=>x.name=="LOD0");var m=r.sharedMesh;var p=m.vertices.Select(r.transform.TransformPoint).ToArray();var uv=m.uv;var nn=m.normals;var tang=m.tangents;var t=new Texture2D(2,2,TextureFormat.RGBA32,false,true);t.LoadImage(File.ReadAllBytes(NurseVisualOptimization.Folder+"/Atlas_Albedo.png"));var nt=new Texture2D(2,2,TextureFormat.RGBA32,false,true);nt.LoadImage(File.ReadAllBytes(NurseVisualOptimization.Folder+"/Atlas_Normal.png"));var rows=new List<string>();var values=new List<Tuple<float,string>>();foreach(var g in Enumerable.Range(0,p.Length).Where(i=>p[i].y>1.64f&&p[i].y<1.72f&&Mathf.Abs(p[i].x)<.08f&&p[i].z>.025f).GroupBy(i=>Mathf.RoundToInt(p[i].x*100000)+","+Mathf.RoundToInt(p[i].y*100000)+","+Mathf.RoundToInt(p[i].z*100000))){var ids=g.ToArray();for(int a=0;a<ids.Length;a++)for(int b=a+1;b<ids.Length;b++){int i=ids[a],j=ids[b];var c=t.GetPixelBilinear(uv[i].x,uv[i].y);var d=t.GetPixelBilinear(uv[j].x,uv[j].y);float color=Vector3.Distance(new Vector3(c.r,c.g,c.b),new Vector3(d.r,d.g,d.b));Func<int,Vector3> normal=k=>{var s=nt.GetPixelBilinear(uv[k].x,uv[k].y);var tangent=new Vector3(tang[k].x,tang[k].y,tang[k].z);return (tangent*(s.r*2-1)+Vector3.Cross(nn[k],tangent)*tang[k].w*(s.g*2-1)+nn[k]*(s.b*2-1)).normalized;};float angle=Vector3.Angle(normal(i),normal(j));values.Add(Tuple.Create(color+angle/180f,"position="+p[i].ToString("F5")+" UV="+uv[i].ToString("F5")+" / "+uv[j].ToString("F5")+" albedoDelta="+color+" tangentWorldNormalAngle="+angle+" vertexNormalAngle="+Vector3.Angle(nn[i],nn[j])));}}rows.Add("Coincident forehead seam vertex pairs="+values.Count);rows.AddRange(values.OrderByDescending(v=>v.Item1).Take(40).Select(v=>v.Item2));File.WriteAllLines(NurseVisualOptimization.Out+"/forehead-seam-audit.txt",rows);}
}

